/**
 * 安全解混淆函数 (仅在主进程运行时内存中动态解析)
 */
function deobfuscate(encoded: string, key = 0x6e): string {
  try {
    const buf = Buffer.from(encoded, 'base64');
    for (let i = 0; i < buf.length; i++) {
      buf[i] = buf[i] ^ key;
    }
    return buf.toString('utf8');
  } catch {
    return '';
  }
}

/**
 * 内存动态解密缓存，避免每次重复计算，同时对外部进程完全黑盒
 */
